151→// ─────────────────────────── Tool 1: queryMarkers ──────────────────
152→
153→export interface QueryMarkersArgs {
154→  runId: string;
155→  thread?: string;
156→  sortBy?: 'selfMs' | 'totalMs' | 'count';
157→  topN?: number;
158→}
159→
160→export interface MarkerRow {
161→  markerName: string;
162→  thread: string;
163→  sumSelfMs: number;
164→  sumTotalMs: number;
165→  sampleCount: number;
166→  presentInFrames: number;
167→  avgSelfMsPerPresentFrame: number;
168→  maxSelfMs: number;
169→  maxSelfFrameIndex: number;
170→}
171→
172→export interface QueryMarkersResult {
173→  data: MarkerRow[];
174→  provenance: Provenance;
175→}
176→
177→export function queryMarkers(
178→  db: Database.Database,
179→  args: QueryMarkersArgs
180→): QueryMarkersResult {
181→  const { runId, thread, sortBy = 'selfMs', topN = 20 } = args;
182→  const effectiveTopN = Math.min(topN, 50);
183→
184→  const orderCol =
185→    sortBy === 'totalMs'
186→      ? 'sum_total_ms'
187→      : sortBy === 'count'
188→      ? 'sample_count'
189→      : 'sum_self_ms';
190→
191→  // Optimized: avoid correlated subquery by using a window function to find
192→  // the frame_index corresponding to max self_ms per (marker_name, thread).
193→  // idx_pfms_run_marker_thread_self covers (run_id, marker_name, thread, self_ms DESC, frame_index),
194→  // allowing the GROUP BY to run without a temp B-tree sort and the
195→  // FIRST_VALUE window to pick the top-self_ms frame_index in a single pass.
196→  let sql: string;
197→  const params: unknown[] = [runId];
198→
199→  if (thread) {
200→    params.push(thread);
201→    sql = `
202→      SELECT
203→        marker_name,
204→        thread,
205→        SUM(self_ms)                               AS sum_self_ms,
206→        SUM(total_ms)                              AS sum_total_ms,
207→        COUNT(*)                                   AS sample_count,
208→        COUNT(DISTINCT frame_index)                AS present_in_frames,
209→        SUM(self_ms) / COUNT(DISTINCT frame_index) AS avg_self_ms_per_frame,
210→        MAX(self_ms)                               AS max_self_ms,
211→        FIRST_VALUE(frame_index) OVER (
212→          PARTITION BY marker_name, thread
213→          ORDER BY self_ms DESC
214→          ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
215→        )                                          AS max_self_frame_index
216→      FROM prism_frame_marker_samples
217→      WHERE run_id = ? AND thread = ?
218→      GROUP BY marker_name, thread
219→      ORDER BY ${orderCol} DESC
